#!/usr/bin/env python3
"""Generate Data/overworld/magic_bean_spots_table.asm from Data/overworld/magic_bean_spots.json.

Validates Magic Bean spot coordinates, SRAM progress offsets, and 3-leg flight
tables for Sprites/NPCs/bean_vendor.asm. Supports --check to fail closed if the
generated ASM include has drifted from the JSON source.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

LEGS_PER_SPOT = 3
MAX_SPOTS = 16
HEADER = (
    "; Generated by Scripts/Generate/sync_magic_bean_spots.py from\n"
    "; Data/overworld/magic_bean_spots.json. Do not edit by hand.\n"
)


def parse_int_hex(value: Any, label: str) -> int:
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    if isinstance(value, str):
        s = value.strip()
        if s.startswith("$"):
            return int(s[1:], 16)
        return int(s, 0)
    raise ValueError(f"{label}: expected int or hex string, got {value!r}")


def parse_i8(value: Any, label: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{label}: expected signed 8-bit int, got {value!r}")
    if not -128 <= value <= 127:
        raise ValueError(f"{label}: {value} outside [-128, 127]")
    return value & 0xFF


def parse_u8(value: Any, label: str, *, min_val: int = 0, max_val: int = 255) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{label}: expected int, got {value!r}")
    if not min_val <= value <= max_val:
        raise ValueError(f"{label}: {value} outside [{min_val}, {max_val}]")
    return value


def validate_and_extract(data: dict[str, Any]) -> list[dict[str, Any]]:
    if data.get("schema_version") != 1:
        raise ValueError("schema_version must be 1")
    if data.get("legs_per_spot") != LEGS_PER_SPOT:
        raise ValueError(f"legs_per_spot must be {LEGS_PER_SPOT}")
    spots = data.get("spots")
    if not isinstance(spots, list) or not spots:
        raise ValueError("spots must be a non-empty list")
    if len(spots) > MAX_SPOTS:
        raise ValueError(f"too many spots ({len(spots)} > {MAX_SPOTS})")

    seen_sram: set[int] = set()
    parsed: list[dict[str, Any]] = []
    for i, spot in enumerate(spots):
        if not isinstance(spot, dict):
            raise ValueError(f"spot[{i}] must be an object")
        if spot.get("index") != i:
            raise ValueError(f"spot[{i}].index must equal {i}, got {spot.get('index')!r}")
        name = str(spot.get("name", f"Spot {i}"))
        parent_map = parse_int_hex(spot.get("parent_map"), f"spot[{i}].parent_map")
        if not 0 <= parent_map < 0xC0:
            raise ValueError(f"spot[{i}].parent_map 0x{parent_map:02X} outside 0x00..0xBF")
        sram_low = parse_int_hex(spot.get("sram_low"), f"spot[{i}].sram_low")
        if not 0 <= sram_low <= 0xFF:
            raise ValueError(f"spot[{i}].sram_low 0x{sram_low:02X} outside 0x00..0xFF")
        if sram_low in seen_sram:
            raise ValueError(f"duplicate sram_low 0x{sram_low:02X} at spot[{i}]")
        seen_sram.add(sram_low)

        hx = parse_int_hex(spot.get("home_x"), f"spot[{i}].home_x")
        hy = parse_int_hex(spot.get("home_y"), f"spot[{i}].home_y")
        if not (0 <= hx <= 0x0FFF and 0 <= hy <= 0x0FFF):
            raise ValueError(f"spot[{i}] home ({hx}, {hy}) outside 0..4095")

        legs = spot.get("legs")
        if not isinstance(legs, list) or len(legs) != LEGS_PER_SPOT:
            raise ValueError(f"spot[{i}].legs must have exactly {LEGS_PER_SPOT} entries")
        parsed_legs = []
        for k, leg in enumerate(legs):
            if not isinstance(leg, dict):
                raise ValueError(f"spot[{i}].legs[{k}] must be an object")
            vx = parse_i8(leg.get("x_speed"), f"spot[{i}].legs[{k}].x_speed")
            vy = parse_i8(leg.get("y_speed"), f"spot[{i}].legs[{k}].y_speed")
            tm = parse_u8(leg.get("timer"), f"spot[{i}].legs[{k}].timer")
            dd = parse_u8(leg.get("drag_dir"), f"spot[{i}].legs[{k}].drag_dir", max_val=3)
            parsed_legs.append((vx, vy, tm, dd))

        parsed.append({
            "index": i,
            "name": name,
            "parent_map": parent_map,
            "sram_low": sram_low,
            "home_x": hx,
            "home_y": hy,
            "legs": parsed_legs,
        })
    return parsed


def render_asm(spots: list[dict[str, Any]]) -> str:
    n = len(spots)
    lines = [
        HEADER.rstrip("\n"),
        f"!MagicBean_SpotCount    = {n}",
        f"!MagicBean_MaxSpotIndex = {n - 1}",
        "",
        "MagicBeanSpot_Screens:",
        "  db " + ", ".join(f"${s['parent_map']:02X}" for s in spots),
        "",
        "MagicBeanSpot_SramLow:",
        "  db " + ", ".join(f"${s['sram_low']:02X}" for s in spots),
        "",
        "; Home soil world pixel coordinates per spot:",
    ]
    for s in spots:
        hx, hy = s["home_x"], s["home_y"]
        lines.append(f";   {s['index']}: ${hx:04X}, ${hy:04X} ({hx}, {hy}) OW ${s['parent_map']:02X} ({s['name']})")
    lines.extend([
        "MagicBeanSpot_HomeXLo:",
        "  db " + ", ".join(f"${s['home_x'] & 0xFF:02X}" for s in spots),
        "MagicBeanSpot_HomeXHi:",
        "  db " + ", ".join(f"${(s['home_x'] >> 8) & 0xFF:02X}" for s in spots),
        "MagicBeanSpot_HomeYLo:",
        "  db " + ", ".join(f"${s['home_y'] & 0xFF:02X}" for s in spots),
        "MagicBeanSpot_HomeYHi:",
        "  db " + ", ".join(f"${(s['home_y'] >> 8) & 0xFF:02X}" for s in spots),
        "",
    ])
    for s in spots:
        dx = sum(((vx - 256 if vx >= 128 else vx) * tm) for vx, _, tm, _ in s["legs"]) // 16
        dy = sum(((vy - 256 if vy >= 128 else vy) * tm) for _, vy, tm, _ in s["legs"]) // 16
        tx, ty = s["home_x"] + dx, s["home_y"] + dy
        lines.append(
            f"; Spot {s['index']}: OW ${s['parent_map']:02X} ({s['home_x']},{s['home_y']}) -> "
            f"({tx},{ty}) [{dx:+d}, {dy:+d}] ({s['name']})"
        )

    for label, idx in (
        ("MagicBean_LegXSpeed", 0),
        ("MagicBean_LegYSpeed", 1),
        ("MagicBean_LegTimers", 2),
        ("MagicBean_LegDragDir", 3),
    ):
        lines.append(f"{label}:")
        for s in spots:
            vals = ", ".join(f"${leg[idx]:02X}" for leg in s["legs"])
            lines.append(f"  db {vals}")
        lines.append("")

    return "\n".join(lines).rstrip() + "\n"


def main(argv: list[str] | None = None) -> int:
    root = Path(__file__).resolve().parents[2]
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--input", type=Path, default=root / "Data/overworld/magic_bean_spots.json")
    ap.add_argument("--out-asm", type=Path, default=root / "Data/overworld/magic_bean_spots_table.asm")
    ap.add_argument("--check", action="store_true", help="fail if generated ASM table is stale or missing")
    args = ap.parse_args(argv)

    try:
        data = json.loads(args.input.read_text(encoding="utf-8"))
        spots = validate_and_extract(data)
        text = render_asm(spots)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(f"magic_bean_spots: {exc}", file=sys.stderr)
        return 1

    if args.check:
        current = args.out_asm.read_text(encoding="utf-8") if args.out_asm.exists() else None
        if current != text:
            print(f"magic_bean_spots: {args.out_asm} is stale; run sync_magic_bean_spots.py", file=sys.stderr)
            return 1
        print(f"magic_bean_spots: {len(spots)} spots up to date")
        return 0

    args.out_asm.parent.mkdir(parents=True, exist_ok=True)
    args.out_asm.write_text(text, encoding="utf-8")
    print(f"magic_bean_spots: wrote {args.out_asm} ({len(spots)} spots)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
